def f(g):
    from collections import defaultdict
    H,W=len(g),len(g[0]); cells=defaultdict(list)
    for i,row in enumerate(g):
        for j,v in enumerate(row):
            if v: cells[v].append((i,j))
    shapes=[]
    for c in sorted(cells, key=lambda c: min(j for i,j in cells[c])):
        pts=cells[c]; t=min(i for i,j in pts); l=min(j for i,j in pts)
        h=max(i for i,j in pts)-t+1; w=max(j for i,j in pts)-l+1
        shapes.append((c,h,w,[(i-t,j-l) for i,j in pts]))
    out=[[0]*W for _ in range(H)]; ti=tj=0
    for c,h,w,rel in shapes:
        for di,dj in rel:
            if 0<=ti+di<H and 0<=tj+dj<W: out[ti+di][tj+dj]=c
        ti+=h-1; tj+=w-1
    return out
